:root{--ink:#f5f5f7;--muted:rgba(245, 245, 247, 0.62);--muted-dim:var(--muted);--surface:#0b0b0f;--surface-raised:#16161c;--signal:#2563eb;--line:#ffffff1f;--paper:#fff;--space-1:4px;--space-2:8px;--space-3:1rem;--radius:8px;--radius-pill:999px;--duration:0.6s;--duration-fast:150ms;--ease:cubic-bezier(0.22, 0.61, 0.36, 1);--ease-linear:linear;--sans:"Inter", system-ui, sans-serif;--font-weight-bold:600;--z-modal:100;--shadow-1:0 1px 3px rgba(0, 0, 0, 0.4);--elev-1:0 1px 1px rgb(0 0 0/0.3),0 4px 8px -2px rgb(0 0 0/0.22);--gutter:clamp(16px, 4vw, 48px);--glow:color-mix(in srgb, var(--signal) 40%, transparent);--border-accent:var(--signal)}
.card{--card-pad:12px;padding:var(--card-pad);color:var(--ink);background:var(--surface-raised);border:1px solid var(--line)}
.hint{color:var(--hint-color, #999999)}
.x{margin:var(--made-up-space);color:var(--made-up-ink);border-color:var(--made-up-line)}
.y{transform:translateY(var(--scroll-y))}
.z{width:calc(var(--ds-seg) * 10px)}
